"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";

/* QR images are generated by the application route and must remain native img elements. */
/* eslint-disable @next/next/no-img-element */

type CardRow = { id: string; slug: string; brandName: string; headline: string; published: boolean; createdAt: string };

export default function DashboardClient({ user, cards }: { user: { name: string; email: string; plan: string }; cards: CardRow[] }) {
  const r = useRouter();
  const [rows, setRows] = useState(cards);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [showUpgrade, setShowUpgrade] = useState(false);

  async function createCard() {
    setBusy(true); setErr("");
    const res = await fetch("/api/cards", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ brandName: user.name ? `${user.name}'s Business` : "My Business" }) });
    const j = await res.json().catch(() => ({}));
    if (res.ok) setRows([j.card, ...rows]); else { setErr(j.error || "Could not create card."); if (j.upgrade) setShowUpgrade(true); }
    setBusy(false);
  }

  async function logout() { await fetch("/api/auth/logout", { method: "POST" }); r.push("/"); r.refresh(); }

  return (
    <main className="a-shell min-h-screen">
      <header className="a-nav sticky top-0 z-20"><div className="a-container flex flex-wrap items-center justify-between gap-4 py-4"><Link href="/" className="a-brand text-lg"><span className="a-brand-mark">A<span className="text-[var(--acc)]">.</span></span><span>App<span className="text-[var(--acc)]">istic</span></span></Link><div className="flex items-center gap-3 text-xs"><span className="hidden text-[var(--mut)] sm:inline">{user.email}</span><span className={`a-pill ${user.plan === "pro" ? "border-[var(--acc)] bg-[var(--acc-soft)] text-[var(--acc-strong)]" : ""}`}>{user.plan === "pro" ? "PRO" : "FREE"}</span>{user.plan !== "pro" && <Link href="/dashboard/billing" className="a-btn px-3 py-2 text-xs">Upgrade <span aria-hidden>↗</span></Link>}<button onClick={logout} className="font-bold text-[var(--mut)] hover:text-[var(--txt)]">Log out</button></div></div></header>
      <div className="a-container pb-20 pt-10 sm:pt-14">
        <div className="flex flex-wrap items-end justify-between gap-5"><div><p className="a-eyebrow">Your workspace</p><h1 className="mt-2 text-3xl font-black tracking-[-.055em] sm:text-4xl">Good to see you, {user.name || "there"}.</h1><p className="mt-2 text-sm text-[var(--mut)]">Everything you share with the world, in one calm place.</p></div><button onClick={createCard} disabled={busy} className="a-btn px-5 py-3 text-sm">{busy ? "Creating…" : "+ New card"}</button></div>
        <div className="mt-8 grid gap-3 sm:grid-cols-3"><div className="a-stat"><p className="text-xs font-bold text-[var(--mut)]">Cards in workspace</p><p className="mt-2 text-3xl font-black tracking-tight">{rows.length}</p><p className="mt-1 text-xs text-[var(--mut)]">{user.plan === "pro" ? "of 10 Pro cards" : "of 1 Free card"}</p></div><div className="a-stat"><p className="text-xs font-bold text-[var(--mut)]">Published presence</p><p className="mt-2 text-3xl font-black tracking-tight">{rows.filter((c) => c.published).length}</p><p className="mt-1 text-xs text-[var(--mut)]">live card{rows.filter((c) => c.published).length === 1 ? "" : "s"}</p></div><div className="a-stat"><p className="text-xs font-bold text-[var(--mut)]">Next best action</p><p className="mt-2 text-lg font-black tracking-tight">{rows.length ? "Share your QR" : "Create your card"}</p><p className="mt-1 text-xs text-[var(--mut)]">make the next introduction easier</p></div></div>
        {err && <p role="alert" className="mt-4 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{err}</p>}
        {showUpgrade && <div className="a-card mt-5 flex flex-wrap items-center justify-between gap-4 border-[var(--acc)] p-5"><div><p className="text-sm font-black">You&apos;ve reached the Free plan limit.</p><p className="mt-1 text-sm text-[var(--mut)]">Pro gives you 10 cards, unlimited leads, and CSV export.</p></div><Link href="/dashboard/billing" className="a-btn px-4 py-2.5 text-xs">See Pro <span aria-hidden>↗</span></Link></div>}
        <div className="mt-12 flex items-end justify-between gap-4"><div><p className="a-eyebrow">Your cards</p><h2 className="mt-2 text-2xl font-black tracking-[-.04em]">Build a page worth sharing.</h2></div><span className="hidden text-xs font-bold text-[var(--mut)] sm:inline">{rows.length} total</span></div>
        {rows.length === 0 ? <div className="a-card mt-6 p-12 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[var(--acc-soft)] text-xl font-black text-[var(--acc)]">A.</div><p className="mt-5 font-black">Your first card starts here.</p><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[var(--mut)]">Add your details, links, and products. You can publish whenever it feels ready.</p><button onClick={createCard} disabled={busy} className="a-btn mt-6 px-5 py-3 text-sm">{busy ? "Creating…" : "Create first card"}</button></div> : <div className="mt-6 grid gap-4 lg:grid-cols-2">{rows.map((c) => <CardTile key={c.id} card={c} />)}</div>}
      </div>
    </main>
  );
}

function CardTile({ card: c }: { card: CardRow }) {
  return <article className="a-card a-card-hover overflow-hidden"><div className="flex items-start justify-between gap-4 border-b border-[var(--line)] p-5"><div className="min-w-0"><div className="flex items-center gap-2"><span className={`h-2 w-2 rounded-full ${c.published ? "bg-[var(--success)]" : "bg-[#b7b7b1]"}`} /><p className="truncate font-black">{c.brandName}</p></div><p className="mt-1 truncate text-xs text-[var(--mut)]">appistic.com/c/{c.slug}</p><p className="mt-3 line-clamp-1 text-xs text-[var(--mut-strong)]">{c.headline || "Add a headline to make your card memorable."}</p></div><span className={`a-pill shrink-0 text-[10px] ${c.published ? "border-[#9bd3bd] bg-[#effaf5] text-[var(--success)]" : ""}`}>{c.published ? "LIVE" : "DRAFT"}</span></div><div className="flex items-center gap-4 p-5"><div className="rounded-xl border border-[var(--line)] bg-white p-1.5 shadow-sm"><img src={`/qr/${c.slug}`} alt={`QR code for ${c.brandName}`} className="h-20 w-20" /></div><div className="flex flex-1 flex-col gap-2 sm:flex-row"><Link href={`/editor/${c.id}`} className="a-btn flex-1 px-4 py-2.5 text-center text-xs">Open editor</Link><Link href={`/analytics/${c.id}`} className="a-ghost flex-1 px-4 py-2.5 text-center text-xs">View insights</Link></div></div><div className="flex items-center justify-between border-t border-[var(--line)] px-5 py-3 text-xs"><a href={`/qr/${c.slug}`} download={`${c.slug}-qr.png`} className="font-bold text-[var(--mut)] hover:text-[var(--txt)]">Download QR</a>{c.published ? <a href={`/c/${c.slug}`} target="_blank" rel="noreferrer" className="font-bold text-[var(--acc)]">View live ↗</a> : <span className="text-[var(--mut)]">Finish your details to publish</span>}</div></article>;
}
